<script setup lang="ts">import {ref,onMounted,onUnmounted} from 'vue';import {readUser,clear} from './stores/session';import {useWorkspace} from './hooks/useWorkspace';import {navigation} from './router/navigation';import {ROLES} from './constants/enums';import Login from './pages/Login.vue';import Overview from './pages/Overview.vue';import Packages from './pages/Packages.vue';import Dependencies from './pages/Dependencies.vue';import Scenarios from './pages/Scenarios.vue';import Results from './pages/Results.vue';import Reviews from './pages/Reviews.vue';const user=ref(readUser()),page=ref('overview'),selected=ref('');const{data,error,loading,refresh}=useWorkspace(user);function go(p:string){page.value=p;window.scrollTo(0,0)}function logout(){clear();user.value=null}function open(id:string){selected.value=id;go('results')}onMounted(()=>window.addEventListener('session-expired',logout));onUnmounted(()=>window.removeEventListener('session-expired',logout));</script><template><Login v-if="!user" @login="user=$event"/><div v-else class="shell"><aside class="sidebar"><a class="brand" @click="go('overview')">铎川工务<span>DUOCHUAN / WORKS ATLAS</span></a><p class="side-note">工作包<br/>关键路径风险图册</p><nav><button v-for="n in navigation" :key="n.id" :class="{active:page===n.id}" @click="go(n.id)"><i>{{n.code}}</i>{{n.label}}</button></nav><div class="account"><b>{{ROLES[user.role]}}</b><small>{{user.email}}</small><button @click="logout">退出计划图册</button></div></aside><main class="content"><div class="topbar"><span>DUOCHUAN / FS DEPENDENCY & TIME RISK</span><span>模拟工务计划 / 2026.11</span></div><div v-if="error" role="alert" class="notice error">{{error}}<button @click="refresh">重试加载</button></div><p v-if="loading">正在读取工作包图册…</p><template v-else><Overview v-if="page==='overview'" :data="data" @go="go"/><Packages v-else-if="page==='packages'" :data="data" :can-write="user.role!=='viewer'" :refresh="refresh"/><Dependencies v-else-if="page==='dependencies'" :data="data" :can-write="user.role!=='viewer'" :refresh="refresh"/><Scenarios v-else-if="page==='scenarios'" :data="data" :can-write="user.role!=='viewer'" :refresh="refresh" @open="open"/><Results v-else-if="page==='results'" :data="data" :selected="selected"/><Reviews v-else :data="data" :can-write="user.role!=='viewer'" :is-admin="user.role==='admin'" :refresh="refresh"/></template><footer>铎川工务 / 模拟工作包 · 独立工期假设，不作资源排程或交付保证</footer></main></div></template>